-- Refresh-token rotation + revocation. Each row is the SHA-256 hash of an opaque
-- refresh token held by one client. Tokens rotate on use (old revoked, replacement
-- issued in the same Family); presenting a revoked token revokes the whole family.
-- See RefreshTokenService / AuthService.RefreshTokenAsync.
BEGIN;

CREATE TABLE IF NOT EXISTS public."RefreshTokens" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "TokenHash" character varying(128) NOT NULL,
    "Family" uuid NOT NULL,
    "ExpiresAt" timestamp with time zone NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "RevokedAt" timestamp with time zone,
    "ReplacedByTokenHash" character varying(128),
    CONSTRAINT "PK_RefreshTokens" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_RefreshTokens_Users_UserId" FOREIGN KEY ("UserId")
        REFERENCES public."Users" ("Id") ON DELETE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_RefreshTokens_TokenHash"
    ON public."RefreshTokens" ("TokenHash");
CREATE INDEX IF NOT EXISTS "IX_RefreshTokens_UserId"
    ON public."RefreshTokens" ("UserId");
CREATE INDEX IF NOT EXISTS "IX_RefreshTokens_Family"
    ON public."RefreshTokens" ("Family");

COMMIT;
